+    let (world, mut h) = plasma_doc();
+    let p0 = OpParams::PlasmaProfile(plasma_op());
+    h.execute(&world, CreateOperation::new(&world, "Plasma1", TORCH, SrcRef::Entity("plate".into()), p0.clone()).expect("op"));
