+    let (first, last) = (&path.moves[t.on], &path.moves[t.off]);
+    assert!(first.arc.is_some() && last.arc.is_some(), "outline leads are arcs");
+    // Pierce and lead-out end stand off the plate (outside it).
+    for q in [first.from, last.to] {
